/bin/zsh -lc "node - <<'NODE'
const fs = require('fs');
const base = 'docs/design/features/collaboration-insight-redesign/evidence/raw';
const data = JSON.parse(fs.readFileSync("'`${base}/autorun-results.json`, '"'utf8'));
for (const sample of data.samples) {
  const name = sample.view === 'network' ? 'network-100' : sample.view === 'impact' ? 'impact-500' : 'lineage-2200';
  fs.writeFileSync("'`${base}/${name}.json`, JSON.stringify(sample, null, 2) + '"'\\n');
}
const rows = [['view','scale','rendered_nodes','rendered_edges','first_interactive_ms','draw_ms_p95','estimated_fps_p95','js_heap_mb','budget_ms_per_frame','pass','interactions_verified']];
for (const sample of data.samples) rows.push([sample.view, sample.requested_scale, sample.rendered_nodes, sample.rendered_edges, sample.first_interactive_ms, sample.draw_ms_p95, sample.estimated_fps_p95, sample.js_heap_mb, sample.budget_ms_per_frame, sample.pass, sample.interactions_verified]);
fs.writeFileSync("'`${base}/prototype-measurements.csv`, rows.map((row) => row.join('"',')).join('\\n') + '\\n');
const source = fs.readFileSync('web/src/pages/InsightCollaboration.tsx', 'utf8');
const baseline = {
  captured_at: new Date().toISOString(),
  source_file: 'web/src/pages/InsightCollaboration.tsx',
  source_commit: require('child_process').execSync('git rev-parse HEAD').toString().trim(),
  current_renderer: 'React SVG groups plus text labels, accumulated on the main thread from /collaboration-effects pages',
  svg_react_surfaces: {
    svg_elements: (source.match(/<svg/g) || []).length,
    edge_group_mapping: /view\\.edges\\.map/.test(source),
    node_group_mapping: /view\\.nodes\\.map/.test(source),
    text_label_rendering: (source.match(/<text/g) || []).length,
    wheel_handler: /onWheel=/.test(source),
    pointer_handlers: /onPointerDown=|pointerdown/.test(source),
    evidence_drawer: /EvidenceDrawer/.test(source),
  },
  bottleneck_baseline: [
    'Default unfiltered request asks the current endpoint for cluster LOD but still renders one SVG group per returned node and edge.',
    'The current page has no view param, so the initial visual surface mixes agent-agent, agent-task, plan/stage/task, dependency, review, and Evidence entry semantics.',
    'Viewport culling is not a renderer boundary; React still owns every returned node/edge element in the SVG tree.',
    'Moving to better force/community/DAG layouts inside this component would put layout work on the main React render path unless moved to a Worker/server cache.'
  ]
};
fs.writeFileSync("'`${base}/current-page-baseline.json`, JSON.stringify(baseline, null, 2) + '"'\\n');
